H=Path(__file__).resolve().parent;D=H/'flat_ground_pose_D3_run_v1';sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest();seal=json.loads((D/'artifact_manifest_post_close.json').read_text());assert all(sha(f)==s for f,s in seal['artifact_sha256'].items());rows=json.loads((D/'policy_records.json').read_text());Y,X=np.mgrid[:480,:640];K=584.8888888888889;ray=np.stack([(X-319.5)/K,(Y-239.5)/K,np.ones_like(X)],axis=-1);answers=[]
