 valid=np.isfinite(uv).all(-1)&(p[:,:,2]>0);safe=np.where(np.isfinite(uv),uv,0);u=np.rint(safe[:,:,0]).astype(np.int64);v=np.rint(safe[:,:,1]).astype(np.int64);valid&=(u>=0)&(u<640)&(v>=0)&(v<480);uc=np.clip(u,0,639);vc=np.clip(v,0,479);mutual=target['left']&~mask['left']&valid&~mask['right'][vc,uc]&target['right'][vc,uc]&np.isfinite(gt['right_depth_m'][vc,uc])&(np.abs(gt['right_depth_m'][vc,uc]-p[:,:,2])<=.02);metrics['left_target_points_bilaterally_visible']=int(mutual.sum())
 ids=raw['query_pixel_id'].astype(int);qual=target['left'].reshape(-1)[ids];truth=world['left'].reshape(-1,3)[ids];errors=np.linalg.norm(raw['world']-truth,axis=1);metrics['accepted_source_queries_on_visible_target']=int(qual.sum());metrics['accepted_target_queries_correct_le_point1']=int((qual&np.isfinite(errors)&(errors<=.1)).sum());metrics['accepted_target_query_precision']=None if not qual.any() else float((np.isfinite(errors[qual])&(errors[qual]<=.1)).mean())
 row=rows[i]['local'];mp=np.load(D/'maps'/f'frame_{i:03d}.npz');birth_values=np.unique(mp['hypothesis_birth_time'][np.isfinite(mp['hypothesis_birth_time'])]);assert len(birth_values)<=1;born=float(birth_values[0]) if len(birth_values) else float('-inf');metrics.update(frame=i,time_s=row['time_s'],model_geometry_birth_s=born if np.isfinite(born) else None,model_geometry_age_s=row['time_s']-born if np.isfinite(born) else None,model_grid_cells=int(np.isin(mp['provenance'],[6,7]).sum()),measured_hazard_cells=int(np.isfinite(mp['hazard_time']).sum()),measured_floor_cells=int(np.isfinite(mp['floor_time']).sum()),reference_version=row['local_reference_version'],reference_installed_time_s=row['reference_installed_time_s'],moving_possible_geometry_consumed=row['moving_geometry_consumed'],model_not_observation=True);answers.append(metrics)
